'use strict';

/**
 * Phase 69 Plan 01 (MCP-01-a): integrity of the frozen 8a058bdf tools/list.
 *
 * tests/fixtures/mcp-tools-list-8a058bdf.json is the Phase 66 baseline
 * tools/list (72 tools), generated by scripts/mcp/tools-list-baseline.mjs
 * from a temp build of the pin. Every Phase 69 gate (shape freeze, budget)
 * reads it, so this suite proves it was not hand-edited:
 *   - meta.sha256 equals sha256(canonicalJson(tools));
 *   - every meta field equals what the generator writes, and the file bytes
 *     equal the generator's serialization, so any byte edit fails;
 *   - meta.sdkVersion / meta.zodVersion equal the installed mcp/node_modules
 *     versions (a dependency bump fails with a regeneration hint, not with a
 *     phantom wire diff);
 *   - 72 unique names, and toolsListDigest equals the 66.1 baseline digest.
 *
 * It never reads git history (CI clones are shallow; D-04).
 *
 * Run: node tests/mcp-tools-list-baseline.test.js
 */

const fs = require('fs');
const path = require('path');
const { pathToFileURL } = require('url');

const HELPER_PATH = path.join(__dirname, 'helpers', 'mcp-in-process.mjs');
const PIN_COMMIT = '8a058bdf0d17c1e3e79ec3104cc1996326b4c402';
const GENERATOR_COMMAND = 'node scripts/mcp/tools-list-baseline.mjs --write';
const REGENERATE_HINT = 'regenerate with node scripts/mcp/tools-list-baseline.mjs --write at the pin';
// The value Phase 66.1 pins as BASELINE_8A058BDF_TOOLS_DIGEST
// (tests/mcp-settings-tool-contract.test.js).
const BASELINE_8A058BDF_TOOLS_DIGEST = Object.freeze({
  count: 72,
  sha256: '8321cc7234a7e1d817b5a3e818e75e243d76e60d1911d88b410d38147c8c4a05',
});
const META_KEYS = ['command', 'count', 'sdkVersion', 'sha256', 'sourceCommit', 'toolsListDigest', 'zodVersion'];

let passed = 0;
let failed = 0;

function check(cond, msg) {
  if (cond) { passed++; console.log('  PASS:', msg); }
  else { failed++; console.error('  FAIL:', msg); }
}

(async () => {
  const h = await import(pathToFileURL(HELPER_PATH).href);
  const fixturePath = path.join(h.REPO_ROOT, h.FIXTURE_RELATIVE_PATH);
  const raw = fs.readFileSync(fixturePath, 'utf8');
  const fixture = JSON.parse(raw);
  const meta = fixture.meta || {};
  const tools = Array.isArray(fixture.tools) ? fixture.tools : [];

  console.log('\n--- fixture self-verification ---');
  const computedSha = h.sha256Hex(h.canonicalJson(tools));
  check(computedSha === meta.sha256,
    `sha256(canonicalJson(tools)) equals meta.sha256 (${computedSha})`);
  check(JSON.stringify(Object.keys(meta).sort()) === JSON.stringify(META_KEYS),
    `meta has exactly the generator's keys (${META_KEYS.join(', ')})`);
  check(meta.sourceCommit === PIN_COMMIT, `meta.sourceCommit is the Phase 66 pin ${PIN_COMMIT}`);
  check(meta.command === GENERATOR_COMMAND, `meta.command is "${GENERATOR_COMMAND}"`);
  check(meta.count === tools.length, `meta.count (${meta.count}) equals the number of tools (${tools.length})`);
  check(raw === `${JSON.stringify(fixture, null, 2)}\n`,
    'the file bytes equal the generator serialization (no hand-formatting)');
  check(h.canonicalJson(tools) === JSON.stringify(tools),
    'tools are stored in canonical form (sorted keys, no undefined values)');
  check(tools.every((tool, index) => index === 0 || String(tools[index - 1].name) < String(tool.name)),
    'tools are sorted by name with no duplicates');

  console.log('\n--- SDK and zod versions ---');
  const installed = h.readInstalledVersions();
  check(installed.sdkVersion === meta.sdkVersion,
    `installed @modelcontextprotocol/sdk ${installed.sdkVersion} equals meta.sdkVersion ${meta.sdkVersion}`
      + (installed.sdkVersion === meta.sdkVersion ? '' : ` -- ${REGENERATE_HINT}`));
  check(installed.zodVersion === meta.zodVersion,
    `installed zod ${installed.zodVersion} equals meta.zodVersion ${meta.zodVersion}`
      + (installed.zodVersion === meta.zodVersion ? '' : ` -- ${REGENERATE_HINT}`));

  console.log('\n--- names and the 66.1 digest ---');
  const names = tools.map((tool) => tool && tool.name);
  check(names.length === 72, `the fixture has 72 tools (got ${names.length})`);
  check(new Set(names).size === names.length, 'every fixture tool name is unique');
  check(names.every((name) => typeof name === 'string' && name.length > 0), 'every fixture tool has a name');
  check(!names.includes(h.SETTINGS_TOOL_NAME), 'the Phase 66.1 settings tool is not in the 8a058bdf baseline');
  const digest = h.toolsListDigest(tools);
  check(digest.count === BASELINE_8A058BDF_TOOLS_DIGEST.count && digest.sha256 === BASELINE_8A058BDF_TOOLS_DIGEST.sha256,
    `toolsListDigest(fixture.tools) equals the 66.1 BASELINE_8A058BDF_TOOLS_DIGEST (${digest.count}, ${digest.sha256})`);
  check(meta.toolsListDigest === digest.sha256, 'meta.toolsListDigest equals the recomputed digest');

  const figures = {
    count: tools.length,
    descChars: h.descChars(tools),
    paramChars: h.paramChars(tools),
    bytes: h.canonicalBytes({ tools }),
  };
  console.log(`\n  baseline 8a058bdf: ${figures.count} tools; description chars ${figures.descChars}; `
    + `parameter-description chars ${figures.paramChars}; canonical bytes of {tools} ${figures.bytes}`);

  console.log(`\n=== Results: ${passed} passed, ${failed} failed ===`);
  if (failed > 0) {
    console.error(`  The fixture is generated, never hand-edited: ${REGENERATE_HINT} (needs git history).`);
    process.exit(1);
  }
  process.exit(0);
})().catch((err) => {
  console.error('  FAIL: mcp-tools-list-baseline threw:', err && err.stack ? err.stack : err);
  process.exit(1);
});
